+    }
+
+    private void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void markValid(HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(store.getMessages());
+    }
+
+    private static String value(String value) {
+        return value == null ? "" : value;
+    }
+
+    private boolean isFormEmpty() {
+        return value(nameField.getValue()).isEmpty() && value(emailField.getValue()).isEmpty()
+                && value(phoneField.getValue()).isEmpty() && value(messageField.getValue()).isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (isFormEmpty()) {
+            // Nothing to lose, so leaving is not interrupted.
+            return;
+        }
+        pendingNavigation = event.postpone();
+        getLeaveDialog().open();
+    }
+
+    private Dialog getLeaveDialog() {
+        if (leaveDialog == null) {
+            leaveDialog = new Dialog();
+            leaveDialog.setHeaderTitle("Unsaved changes");
+            leaveDialog.setCloseOnEsc(false);
+            leaveDialog.setCloseOnOutsideClick(false);
+            leaveDialog.add(new Paragraph("You have not yet sent what you wrote."));
+
+            Button keepEditing = new Button("Keep editing", e -> resolveNavigation(false));
+            keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+            Button discard = new Button("Discard", e -> resolveNavigation(true));
+            leaveDialog.add(new HorizontalLayout(keepEditing, discard));
+        }
+        return leaveDialog;
+    }
+
+    private void resolveNavigation(boolean proceed) {
+        if (leaveDialog != null) {
+            leaveDialog.close();
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+        pendingNavigation = null;
+        if (action == null) {
+            return;
+        }
+        if (proceed) {
+            action.proceed();
+        } else {
+            // Cancel rather than just forget it, so that the next attempt to
+            // leave is asked about again.
+            action.cancel();
+        }
+    }
+}
